async function completeMobileSso() {
  const params = new URLSearchParams(location.search);
  const sso = params.get("sso");
  if (params.get("mobile_sso") !== "1" || !sso) return;
  const cleanParams = new URLSearchParams();
  if (DM_LANGS.includes(params.get("adf_lang"))) cleanParams.set("adf_lang", params.get("adf_lang"));
  const cleanUrl = location.pathname + (cleanParams.toString() ? `?${cleanParams}` : "") + (location.hash || "");
  try {
    const response = await fetch(SSO_ENDPOINT + "?sso=" + encodeURIComponent(sso), { cache: "no-store" });
    let payload = {};
    try { payload = await response.json(); } catch (error) {}
    if (!response.ok) throw new Error(payload.detail || "App oturumu açılamadı");
    const session = sessionFromApiPayload(payload);
    saveAuth(session);
    saveProfile(profileFromSession(session));
    history.replaceState({}, "", cleanUrl);
  } catch (error) {
    history.replaceState({}, "", cleanUrl);
    window.DM_SSO_ERROR = error;
  }
}
